const VERSION='RCV-V1.0-LOCAL-004';
let state=null, selectedPatientId=null, selectedCaseId=null, currentMain='patients', currentTab='preop', saveTimer=null;

const DEFAULT_DRUGS=[
 {id:'noradrenalina',name:'Noradrenalina',category:'Vasopresor',amount:4,amountUnit:'mg',units:4,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'0.04–2 mcg/kg/min',source:'4 mg; 4 amp/100'},
 {id:'adrenalina',name:'Adrenalina',category:'Vasopresor',amount:1,amountUnit:'mg',units:6,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'0.01–0.5 mcg/kg/min',source:'1 mg; 6 amp/100'},
 {id:'vasopresina',name:'Vasopresina',category:'Vasopresor',amount:20,amountUnit:'UI',units:2,finalVolume:100,diluent:'SF',doseUnit:'UI/min',range:'0.01–0.04 UI/min (otros rangos según contexto)',source:'20 UI; 2 amp/100'},
 {id:'azul_metileno',name:'Azul de metileno',category:'Vasopresor',amount:100,amountUnit:'mg',units:1,finalVolume:100,diluent:'SF',doseUnit:'mg/kg/h',range:'Carga 1.5–2 mg/kg; mantenimiento 0.5–1 mg/kg/h',source:'1% =10 mg/mL; presentación 5–10 mL',manualOnly:true},
 {id:'fenilefrina',name:'Fenilefrina',category:'Vasopresor',amount:10,amountUnit:'mg',units:4,finalVolume:250,diluent:'SF',doseUnit:'mcg/min',range:'Hasta 150–200 mcg/min (verificar protocolo local)',source:'10 mg; 4 amp/250'},
 {id:'dobutamina',name:'Dobutamina',category:'Inotrópico',amount:250,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'2.5–20 mcg/kg/min',source:'250 mg; 2 amp/100'},
 {id:'dopamina',name:'Dopamina',category:'Inotrópico',amount:200,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'5–15 mcg/kg/min',source:'200 mg; 2 amp/100'},
 {id:'milrinona',name:'Milrinona',category:'Inotrópico',amount:10,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'0.35–0.75 mcg/kg/min',source:'10 mg; 2 amp/100'},
 {id:'levosimendan',name:'Levosimendán',category:'Preoperatoria',amount:12.5,amountUnit:'mg',units:1,finalVolume:250,diluent:'DX5%',doseUnit:'mcg/kg/min',range:'0.05–0.5 mcg/kg/min',source:'12.5 mg; 1 amp/250 DX5%',preopOnly:true},
 {id:'isoproterenol',name:'Isoproterenol',category:'Inotrópico',amount:1,amountUnit:'mg',units:1,finalVolume:250,diluent:'SF',doseUnit:'mcg/min',range:'2–10 mcg/min',source:'1 mg; 1 amp/250'},
 {id:'nitroglicerina',name:'Nitroglicerina',category:'Vasodilatador',amount:25,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/min',range:'Titular a TA deseada',source:'25 mg; 2 amp/100'},
 {id:'nitroprusiato',name:'Nitroprusiato',category:'Vasodilatador',amount:50,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'Titular a TA deseada',source:'50 mg; 2 amp/100 CVC'},
 {id:'labetalol',name:'Labetalol',category:'Vasodilatador',amount:20,amountUnit:'mg',units:5,finalVolume:100,diluent:'SF',doseUnit:'mg/h',range:'Titular a TA/FC deseada',source:'20 mg; 5 amp/100'},
 {id:'remifentanilo',name:'Remifentanilo',category:'Sedación/analgesia',amount:5,amountUnit:'mg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/min',range:'Hasta 0.25 mcg/kg/min',source:'5 mg; 2 amp/100'},
 {id:'fentanilo',name:'Fentanilo',category:'Sedación/analgesia',amount:250,amountUnit:'mcg',units:3,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/h',range:'0.7–5 mcg/kg/h',source:'250 mcg/5 mL; 3 amp/100'},
 {id:'midazolam',name:'Midazolam',category:'Sedación/analgesia',amount:15,amountUnit:'mg',units:6,finalVolume:100,diluent:'SF',doseUnit:'mg/kg/h',range:'0.02–0.2 mg/kg/h',source:'15 mg/3 mL; 6 amp/100'},
 {id:'dexmedetomidina',name:'Dexmedetomidina',category:'Sedación/analgesia',amount:200,amountUnit:'mcg',units:2,finalVolume:100,diluent:'SF',doseUnit:'mcg/kg/h',range:'0.2–1.4 mcg/kg/h',source:'200 mcg/2 mL; 2 amp/100'},
 {id:'propofol',name:'Propofol',category:'Sedación/analgesia',amount:200,amountUnit:'mg',units:5,finalVolume:100,diluent:'SF',doseUnit:'mg/kg/h',range:'0.3–3 mg/kg/h',source:'10 mg/mL → 200 mg; 5/100'},
 {id:'amiodarona',name:'Amiodarona',category:'Antiarrítmico',amount:150,amountUnit:'mg',units:1,finalVolume:500,diluent:'DX5%',doseUnit:'mg/h',range:'Carga 5 mg/kg; mantenimiento según protocolo',source:'150 mg; dilución variable',manualOnly:true},
 {id:'lidocaina2',name:'Lidocaína 2%',category:'Antiarrítmico',amount:400,amountUnit:'mg',units:5,finalVolume:250,diluent:'SF',doseUnit:'mg/min',range:'1–4 mg/min',source:'20 mg/mL x20mL=400 mg; 5/250'},
 {id:'lidocaina1',name:'Lidocaína 1%',category:'Antiarrítmico',amount:200,amountUnit:'mg',units:5,finalVolume:250,diluent:'SF',doseUnit:'mg/min',range:'Según protocolo',source:'10 mg/mL x20mL=200 mg; 5/250'},
 {id:'tranexamico',name:'Ácido tranexámico',category:'Otros',amount:500,amountUnit:'mg',units:2,finalVolume:250,diluent:'SF',doseUnit:'mg/h',range:'Bolo 1 g; mantenimiento 1 g/250 mL/24 h',source:'500 mg; 2 amp/250'}
];

const $=q=>document.querySelector(q); const $$=q=>[...document.querySelectorAll(q)];
const esc=s=>String(s??'').replace(/[&<>'"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;',"'":'&#39;','"':'&quot;'}[c]));
const uid=p=>p+'_'+Math.random().toString(36).slice(2,9)+Date.now().toString(36);
const now=()=>new Date().toISOString();
const n=v=>{let x=parseFloat(String(v??'').replace(',','.'));return Number.isFinite(x)?x:null};
const fmt=(x,d=3)=>Number.isFinite(x)?x.toFixed(d).replace('.',','):'—';
const boolSel=(v,blank=true)=>`${blank?'<option value="">— seleccionar —</option>':''}<option value="no" ${v==='no'?'selected':''}>No</option><option value="si" ${v==='si'?'selected':''}>Sí</option>`;
const opts=(arr,v,blank=true)=>`${blank?'<option value="">— seleccionar —</option>':''}`+arr.map(x=>{let val=Array.isArray(x)?x[0]:x, lab=Array.isArray(x)?x[1]:x;return `<option value="${esc(val)}" ${String(v)===String(val)?'selected':''}>${esc(lab)}</option>`}).join('');
function getByPath(obj,path){return path.split('.').reduce((a,k)=>a==null?undefined:a[k],obj)}
function setByPath(obj,path,value){let p=path.split('.'),o=obj;for(let i=0;i<p.length-1;i++){if(o[p[i]]==null||typeof o[p[i]]!=='object')o[p[i]]={};o=o[p[i]]}o[p[p.length-1]]=value}

async function api(path,opt={}){let r=await fetch(path,opt); if(!r.ok)throw new Error(await r.text()); return r.headers.get('content-type')?.includes('json')?r.json():r.text()}
async function load(){state=await api('/api/state'); if(!state.drugConfig?.length){state.drugConfig=structuredClone(DEFAULT_DRUGS); await saveNow()} render()}
function markSaving(){let el=$('#saveStatus');if(el){el.textContent='Guardando…';el.className='version warn'}}
function scheduleSave(){markSaving();clearTimeout(saveTimer);saveTimer=setTimeout(saveNow,350)}
async function saveNow(){try{await api('/api/state',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(state)});let el=$('#saveStatus');if(el){el.textContent='✓ Guardado';el.className='version ok'}}catch(e){let el=$('#saveStatus');if(el){el.textContent='⚠ Error de guardado';el.className='version bad'};console.error(e)}}
function patient(){return state.patients.find(p=>p.id===selectedPatientId)}
function ccase(){return patient()?.cases?.find(c=>c.id===selectedCaseId)}
function updateSection(name){let c=ccase(); if(c){c.sectionUpdated??={};c.sectionUpdated[name]={at:now(),by:state.currentUser?.name||'Usuario local'};c.updatedAt=now()}}
const CONDITIONAL_PATHS=new Set([
 'context','preop.pad','preop.cea','preop.lung','preop.cancer','preop.glp1',
 'surgery.surgeon','surgery.cec.used','surgery.transfusion.yes',
 'surgery.cabg.lima.yes','surgery.cabg.lima.sequential','surgery.cabg.rima.yes','surgery.cabg.rima.sequential','surgery.cabg.venous.yes','surgery.cabg.venous.count',
 'pop.hemodynamics.swan','pop.resp.arm','pop.resp.o2type','pop.mcs.yes','pop.pacer.yes','pop.pacer.atrial','pop.pacer.ventricular','pop.drains.yes','pop.arrivalTransfusion.yes'
]);
function bindValue(e){
 let c=ccase(); if(!c)return; let path=e.target.dataset.bind; if(!path)return;
 let val=e.target.type==='checkbox'?e.target.checked:e.target.value;
 setByPath(c,path,val);
 if(path==='context'&&val==='ambulatorio'){c.character='Programada';c.admissionDate='';c.preop??={};c.preop.shock='';c.preop.levosimendan='';}
 updateSection((path.split('.')[0]||currentTab)); scheduleSave();
 if(CONDITIONAL_PATHS.has(path)) render();
}
function bindPatientValue(e){let p=patient();if(!p)return;let path=e.target.dataset.patientBind;if(!path)return;p[path]=e.target.value;p.name=[p.lastName,p.firstName].filter(Boolean).join(', ');scheduleSave();}
function patientDisplay(p){return [p.lastName,p.firstName].filter(Boolean).join(', ')||p.name||'Sin nombre'}
function patientIds(p){let a=[];if(p.dni)a.push('DNI '+p.dni);if(p.hc)a.push('HC '+p.hc);return a.join(' · ')||'Sin identificador visible'}

function appbar(){return `<div class="appbar"><div class="brandrow"><div><div class="brand">RCV – Recuperación Cardiovascular</div><div class="version">${VERSION} · datos locales SQLite</div></div><div><div id="saveStatus" class="version ok">✓ Guardado</div><div class="version">${esc(state.currentUser?.name)} · ${esc(state.currentUser?.role)}</div></div></div><div class="nav"><button data-main="patients" class="${currentMain==='patients'?'active':''}">Pacientes</button><button data-main="drugs" class="${currentMain==='drugs'?'active':''}">Configuración drogas</button><button data-main="data" class="${currentMain==='data'?'active':''}">Backup / datos</button></div></div>`}

function render(){let app=$('#app');app.innerHTML=appbar()+`<div class="shell">${currentMain==='patients'?renderPatients():currentMain==='drugs'?renderDrugConfig():renderData()}</div>`; wire()}
function renderPatients(){if(selectedCaseId&&ccase()) return renderCase();return `<div class="toolbar"><button class="btn primary" id="newCaseBtn">+ Nuevo paciente / caso</button><input id="searchCases" placeholder="Buscar apellido, DNI o HC" style="min-width:280px;border:1px solid var(--line);border-radius:8px;padding:8px"></div><div class="card pad"><h2 class="title">Pacientes</h2>${state.patients.length?`<div class="caseList">${state.patients.map(p=>p.cases.map(c=>caseRow(p,c)).join('')).join('')}</div>`:'<div class="goodnotice">No hay pacientes ni casos cargados. La base está vacía para pruebas.</div>'}</div>`}
function caseRow(p,c){let proc=procedureLabel(c),display=patientDisplay(p),ids=patientIds(p);let search=(display+' '+(p.dni||'')+' '+(p.hc||'')+' '+proc).toLowerCase();return `<div class="caseRow" data-search="${esc(search)}"><div><h3>${esc(display)} · ${esc(ids)}</h3><div class="smalltxt">${esc(proc||'Procedimiento no definido')} · ${esc(c.context==='ambulatorio'?'Ambulatorio':'Internado')} · ${esc(c.character||'')}</div><div class="statbar"><span class="pill">PREOP</span><span class="pill">CX</span><span class="pill">POP</span><span class="pill">72H</span><span class="pill">ALTA</span></div></div><button class="btn" data-open-case="${p.id}|${c.id}">Abrir</button></div>`}
function procedureLabel(c){let s=c.surgery?.procedures||{}, a=[];if(s.crm)a.push('CRM');if(s.rva)a.push('RVA');if(s.plastiaA)a.push('Plastia Ao');if(s.rvm)a.push('RVM');if(s.plastiaM)a.push('Plastia mitral');if(s.rvt)a.push('RVT');if(s.plastiaT)a.push('Plastia tricuspídea');if(s.aorta)a.push('Aorta');if(s.tx)a.push('Trasplante');return a.join(' + ')||((c.indications||[]).join(' + '))}

function newCaseModal(){return `<div class="modal" id="modal"><div class="modalbox"><h2 class="title">Nuevo paciente / caso</h2><div class="grid2"><div class="field"><label>Apellido *</label><input id="npLastName"></div><div class="field"><label>Nombre *</label><input id="npFirstName"></div><div class="field"><label>DNI *</label><input id="npDNI" inputmode="numeric"></div><div class="field"><label>HC (opcional)</label><input id="npHC"></div><div class="field"><label>Fecha nacimiento</label><input type="date" id="npDOB"></div><div class="field"><label>Sexo</label><select id="npSex">${opts(['Masculino','Femenino','Otro'],'')}</select></div><div class="field"><label>Contexto PREOP</label><select id="npContext"><option value="ambulatorio">Ambulatorio</option><option value="internado">Internado</option></select></div><div class="field"><label>Carácter</label><select id="npCharacter" disabled><option>Programada</option></select></div><div class="field" id="npAdmissionWrap" style="display:none"><label>Fecha internación</label><input type="date" id="npAdmission"></div><div class="field"><label>Peso (kg)</label><input type="number" step="0.1" id="npWeight"></div><div class="field"><label>Talla (cm)</label><input type="number" step="0.1" id="npHeight"></div></div><div class="subtitle">Indicación</div><div class="checkgrid" id="npIndications">${['Enfermedad coronaria','Valvulopatía','Patología aórtica','Endocarditis','IC avanzada','Congénita','Pericardio','Otra'].map(x=>`<label class="check"><input type="checkbox" value="${esc(x)}"> ${esc(x)}</label>`).join('')}</div><div class="toolbar" style="margin-top:16px"><button class="btn primary" id="createCaseBtn">Crear</button><button class="btn" id="closeModalBtn">Cancelar</button></div></div></div>`}
function createCase(){let lastName=$('#npLastName').value.trim(),firstName=$('#npFirstName').value.trim(),dni=$('#npDNI').value.trim(),hc=$('#npHC').value.trim();if(!lastName||!firstName||!dni){alert('Apellido, nombre y DNI son obligatorios');return}let p=state.patients.find(x=>String(x.dni||'').replace(/\D/g,'')===dni.replace(/\D/g,''));if(!p){p={id:uid('p'),lastName,firstName,name:`${lastName}, ${firstName}`,dni,hc,dob:$('#npDOB').value,sex:$('#npSex').value,cases:[]};state.patients.push(p)}else{if(!p.hc&&hc)p.hc=hc;if(!p.lastName)p.lastName=lastName;if(!p.firstName)p.firstName=firstName;p.name=[p.lastName,p.firstName].filter(Boolean).join(', ')}let context=$('#npContext').value;let c={id:uid('c'),createdAt:now(),updatedAt:now(),context,character:context==='ambulatorio'?'Programada':$('#npCharacter').value,admissionDate:context==='internado'?$('#npAdmission').value:'',weight:$('#npWeight').value,height:$('#npHeight').value,indications:$$('#npIndications input:checked').map(x=>x.value),preop:{},surgery:{procedures:{},cabg:{lima:{},rima:{},venous:{grafts:[]}},cec:{}},pop:{hemodynamics:{},resp:{},drugs:{inotropes:[],vasopressors:[],vasodilators:[],sedation:[],antiarrhythmics:[]},pacer:{},drains:{},lab:{}},h72:{},discharge:{},followups:[],documents:{},sectionUpdated:{}};p.cases.push(c);selectedPatientId=p.id;selectedCaseId=c.id;currentTab='preop';scheduleSave();$('#modal')?.remove();render()}

function caseHeader(){let p=patient(),c=ccase();let bmi=(n(c.weight)&&n(c.height))?n(c.weight)/((n(c.height)/100)**2):null;return `<div class="card pad"><div class="headcase"><div><h2>${esc(patientDisplay(p))} · ${esc(patientIds(p))}</h2><div class="smalltxt">${esc(c.context==='ambulatorio'?'PREOP ambulatorio':'PREOP internado')} · ${esc(c.character||'')} · Peso ${esc(c.weight||'—')} kg · IMC ${bmi?fmt(bmi,1):'—'} · ${esc(procedureLabel(c)||'procedimiento no definido')}</div></div><button class="btn" id="backCases">← Pacientes</button></div><div class="tabs">${[['preop','PREOP'],['surgery','CIRUGÍA'],['pop','POP INMEDIATO'],['h72','72 H'],['discharge','ALTA'],['docs','DOCUMENTOS'],['followup','SEGUIMIENTO']].map(([k,l])=>`<button data-tab="${k}" class="${currentTab===k?'active':''}">${l}</button>`).join('')}</div></div>`}
function renderCase(){return caseHeader()+`<div style="height:12px"></div>${currentTab==='preop'?renderPreop():currentTab==='surgery'?renderSurgery():currentTab==='pop'?renderPop():currentTab==='h72'?render72():currentTab==='discharge'?renderDischarge():currentTab==='docs'?renderDocs():renderFollowup()}`}
function section(title,body,status='ok',id=''){let c=ccase(),u=c.sectionUpdated?.[id];return `<div class="section open"><div class="section-h"><strong>${title}</strong><span class="statusdot ${status}">●</span></div><div class="section-b">${body}${u?`<div class="smalltxt" style="margin-top:12px">Última modificación: ${esc(u.by)} · ${new Date(u.at).toLocaleString()}</div>`:''}</div></div>`}
function bindField(label,path,value,type='text',extra=''){let id='f_'+path.replace(/[^a-z0-9]/gi,'_');return `<div class="field"><label>${label}</label><input id="${id}" data-bind="${path}" type="${type}" value="${esc(value??'')}" ${extra}></div>`}
function bindSelect(label,path,value,arr,extra='',blank=true){let id='f_'+path.replace(/[^a-z0-9]/gi,'_');return `<div class="field"><label>${label}</label><select id="${id}" data-bind="${path}" ${extra}>${opts(arr,value,blank)}</select></div>`}
function bindPatientField(label,path,value,type='text',extra=''){let id='pf_'+path.replace(/[^a-z0-9]/gi,'_');return `<div class="field"><label>${label}</label><input id="${id}" data-patient-bind="${path}" type="${type}" value="${esc(value??'')}" ${extra}></div>`}
function checkBind(label,path,checked){return `<label class="check"><input type="checkbox" data-bind="${path}" ${checked?'checked':''}> ${label}</label>`}

function renderPreop(){let c=ccase(),p=c.preop||{}, pt=patient(), amb=c.context==='ambulatorio';let general=`<div class="grid3">${bindPatientField('HC (opcional)','hc',pt.hc||'')}${bindField('Peso (kg)','weight',c.weight,'number','step="0.1"')}${bindField('Talla (cm)','height',c.height,'number','step="0.1"')}${bindSelect('Contexto preoperatorio','context',c.context,[['ambulatorio','Ambulatorio'],['internado','Internado']],"data-special='context'",false)}${bindSelect('Carácter','character',amb?'Programada':c.character,['Programada','Urgente','Emergencia'],amb?'disabled':'',false)}${amb?'':bindField('Fecha internación','admissionDate',c.admissionDate,'date')}</div><div class="hint">En PREOP ambulatorio no se solicitan fecha de internación ni fecha de cirugía. La fecha efectiva de cirugía se registra en CIRUGÍA.</div>`;
let indication=`<div class="checkgrid">${['Enfermedad coronaria','Valvulopatía','Patología aórtica','Endocarditis','IC avanzada','Congénita','Pericardio','Otra'].map(x=>`<label class="check"><input type="checkbox" data-indication="${esc(x)}" ${(c.indications||[]).includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div><div class="subtitle">Procedimiento previsto</div><div class="checkgrid">${['CRM','Reemplazo aórtico','Plastia aórtica','Reemplazo mitral','Plastia mitral','Reemplazo tricuspídeo','Plastia tricuspídea','Cirugía de aorta','Trasplante/VAD','Otro'].map(x=>`<label class="check"><input type="checkbox" data-planproc="${esc(x)}" ${(p.plannedProcedures||[]).includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div>`;
let cv=`<div class="grid3">${bindSelect('Enfermedad coronaria documentada','preop.cad',p.cad,['No','Sí','No disponible'])}${bindSelect('IAM previo','preop.mi',p.mi,['No','Sí','No disponible'])}${bindField('FEVI (%)','preop.ef',p.ef,'number')}${bindSelect('Insuficiencia cardíaca','preop.hf',p.hf,['No','Sí','No disponible'])}${bindSelect('FA/flutter previo','preop.af',p.af,['No','Sí','No disponible'])}${bindSelect('MCP/CDI/CRT','preop.device',p.device,['No','MCP','CDI','CRT-P','CRT-D','No disponible'])}${!amb?bindSelect('Shock durante internación','preop.shock',p.shock,['No','Activo al ingreso a quirófano','Resuelto ≤24 h','Resuelto >24 h','No disponible']):''}${bindSelect('Enfermedad arterial periférica','preop.pad',p.pad,['No','Sí','No disponible'])}${p.pad==='Sí'?bindSelect('EAP sintomática','preop.padSymptomatic',p.padSymptomatic,['No','Sí','No disponible']):''}${p.pad==='Sí'?bindSelect('Claudicación intermitente','preop.claudication',p.claudication,['No','Sí','No disponible']):''}${p.pad==='Sí'?bindSelect('Bypass/angioplastia MMII previa','preop.padIntervention',p.padIntervention,['No','Sí','No disponible']):''}${bindSelect('TVP actual/reciente','preop.dvt',p.dvt,['No','Sí','No disponible'])}${!amb?bindSelect('Levosimendán preoperatorio','preop.levosimendan',p.levosimendan,['No','Sí','No disponible']):''}</div>`;
const carotidOpts=['<50%','50–69%','70–79%','80–89%','90–99%','Oclusión','Desconocido'];let neuro=`<div class="grid3">${bindSelect('ACV previo','preop.stroke',p.stroke,['No','Sí','No disponible'])}${bindSelect('AIT previo','preop.tia',p.tia,['No','Sí','No disponible'])}${bindSelect('Carótida derecha','preop.carotidR',p.carotidR,carotidOpts)}${bindSelect('Carótida izquierda','preop.carotidL',p.carotidL,carotidOpts)}${bindSelect('Endarterectomía carotídea previa','preop.cea',p.cea,['No','Sí','No disponible'])}${p.cea==='Sí'?bindSelect('Lado endarterectomía','preop.ceaSide',p.ceaSide,['Derecha','Izquierda','Bilateral','Desconocido']):''}</div><div class="hint">La enfermedad carotídea significativa se deriva por lado a partir de ≥50%; una carótida puede ser normal y la otra patológica.</div>`;
let resp=`<div class="grid3">${bindSelect('Enfermedad pulmonar crónica','preop.lung',p.lung,['No','Sí','No disponible'])}${p.lung==='Sí'?bindSelect('Severidad','preop.lungSeverity',p.lungSeverity,['Leve','Moderada','Severa','Desconocida']):''}${bindSelect('O₂ domiciliario','preop.homeO2',p.homeO2,['No','Sí','No disponible'])}${bindSelect('Tabaquismo','preop.smoking',p.smoking,['Nunca','Exfumador','Activo','Desconocido'])}${bindSelect('TEP actual/reciente','preop.pe',p.pe,['No','Sí','No disponible'])}</div>`;
let renal=`<div class="grid3">${bindField('Creatinina preop (mg/dL)','preop.creatinine',p.creatinine,'number','step="0.01"')}${bindSelect('ERC conocida','preop.ckd',p.ckd,['No','Sí','No disponible'])}${bindSelect('Diálisis crónica','preop.chronicDialysis',p.chronicDialysis,['No','Sí','No disponible'])}${bindSelect('Diabetes','preop.diabetes',p.diabetes,['No','DM1','DM2','Otra','No disponible'])}${bindField('HbA1c (%)','preop.hba1c',p.hba1c,'number','step="0.1"')}</div>`;
let hem=`<div class="grid3">${bindField('Hb (g/dL)','preop.hb',p.hb,'number','step="0.1"')}${bindField('Hto (%)','preop.hct',p.hct,'number','step="0.1"')}${bindField('Plaquetas','preop.platelets',p.platelets,'number')}</div>`;
let nut=`<div class="grid3">${bindField('Albúmina (g/dL, opcional)','preop.albumin',p.albumin,'number','step="0.1"')}${bindSelect('Pérdida involuntaria >5%/6 meses','preop.weightLoss',p.weightLoss,['No','Sí','No disponible'])}</div><div class="hint">Módulo secundario/QI; no bloquea el cierre estadístico.</div>`;
let onc=`<div class="grid3">${bindSelect('Antecedente oncológico','preop.cancer',p.cancer,['No','Sí','No disponible'])}${p.cancer==='Sí'?bindSelect('Estado oncológico','preop.cancerStatus',p.cancerStatus,['Activo','En tratamiento','En remisión / sin evidencia de enfermedad','Tratamiento finalizado ≤6 meses','Tratamiento finalizado >6 meses','Desconocido']):''}${p.cancer==='Sí'?bindSelect('Órgano / sistema','preop.cancerSite',p.cancerSite,['Colon/recto','Pulmón','Próstata','Mama','Ovario/ginecológico','Hígado','Piel/melanoma','SNC/cerebro','Leucemia','Linfoma','Otro']):''}${p.cancer==='Sí'?bindSelect('Quimioterapia reciente','preop.recentChemo',p.recentChemo,['No','Sí','No disponible']):''}${p.cancer==='Sí'?bindSelect('Radioterapia torácica previa','preop.thoracicRT',p.thoracicRT,['No','Sí','No disponible']):''}</div>`;
let glp=`<div class="grid3">${bindSelect('aGLP-1 / GIP-GLP-1','preop.glp1',p.glp1,['No','Sí'])}${p.glp1==='Sí'?bindSelect('Droga','preop.glp1Drug',p.glp1Drug,['Semaglutida','Liraglutida','Dulaglutida','Tirzepatida','Otra']):''}${p.glp1==='Sí'?bindField('Última dosis','preop.glp1Last',p.glp1Last,'date'):''}${p.glp1==='Sí'?bindSelect('Síntomas GI relevantes','preop.glp1GI',p.glp1GI,['No','Sí']):''}${p.glp1==='Sí'?bindSelect('Gastroparesia conocida/sospechada','preop.gastroparesis',p.gastroparesis,['No','Sí','Desconocido']):''}</div>`;
let scores=`<div class="grid3">${bindField('EuroSCORE II (%)','preop.euroscore',p.euroscore,'number','step="0.01"')}${bindField('ArgenSCORE','preop.argenscore',p.argenscore,'number','step="0.01"')}${bindField('STS (%)','preop.sts',p.sts,'number','step="0.01"')}</div><div class="hint">Los scores pueden quedar no cargados sin impedir avanzar.</div>`;
let checklist=`<div class="checkgrid">${['Anestesia','Odontología','Infectología','Hematología','Endocrinología','Kinesiología','Nutrición','Neumonología','Nefrología','Neurología','Cirugía vascular'].map(x=>{let v=p.checklist?.[x]||'';return `<div class="field"><label>${x}</label><select data-checklist="${esc(x)}">${opts(['Pendiente','Realizado','No indicado','No disponible'],v)}</select></div>`}).join('')}</div><div class="hint">En cirugía valvular urgente de paciente internado, Odontología puede mantenerse como requisito. Reserva de sangre no se muestra como pendiente.</div>`;
return `<div class="card">${section('1. Datos generales',general,'ok','general')}${section('2. Indicación / procedimiento previsto',indication,'ok','indication')}${section('3. Cardiovascular',cv,'ok','cardiovascular')}${section('4. Neurológico / carótidas',neuro,'ok','neuro')}${section('5. Respiratorio',resp,'ok','resp')}${section('6. Renal / metabólico',renal,'ok','renal')}${section('7. Hematológico',hem,'ok','hematology')}${section('8. Nutricional',nut,'idle','nutrition')}${section('9. Oncológico',onc,'ok','oncology')}${section('10. Medicación / seguridad',glp,'ok','meds')}${section('11. Scores',scores,'ok','scores')}${section('12. Checklist prequirúrgica',checklist,'warn','checklist')}</div>`}

const LIMA_SEQ=['Ramus','Circunfleja','1ra Marginal','2da Marginal','1ra Diagonal','2da Diagonal'];
const RIMA_DST=['CD proximal','CD media','CD distal','Tronco PL','Descendente posterior','Ramus','Circunfleja','1ra Marginal','2da Marginal','1ra Diagonal','2da Diagonal'];
const VENOUS_DST=['DA proximal','DA media','DA distal',...RIMA_DST];
function multiCheck(prefix,arr,selected=[]){return `<div class="checkgrid">${arr.map(x=>`<label class="check"><input type="checkbox" data-multi="${prefix}" value="${esc(x)}" ${(selected||[]).includes(x)?'checked':''}> ${esc(x)}</label>`).join('')}</div>`}
function renderSurgery(){let c=ccase(),s=c.surgery||{},proc=s.procedures||{},cab=s.cabg||{lima:{},rima:{},venous:{grafts:[]}},l=cab.lima||{},r=cab.rima||{},v=cab.venous||{grafts:[]};let general=`<div class="grid3">${bindField('Fecha cirugía (entrada a quirófano)','surgery.date',s.date,'date')}${bindField('Hora entrada quirófano','surgery.orTime',s.orTime,'time')}${bindField('Hora ingreso UCO','surgery.ucoTime',s.ucoTime,'time')}${bindSelect('Cirujano','surgery.surgeon',s.surgeon,['Dr Bastianelli','Dr Tenorio','Dr Michel David','Otro'])}${s.surgeon==='Otro'?bindField('Otro cirujano','surgery.otherSurgeon',s.otherSurgeon):''}</div>`;
let procs=`<div class="checkgrid">${[['crm','CRM'],['rva','Reemplazo valvular aórtico'],['plastiaA','Plastia aórtica/anillo'],['rvm','Reemplazo mitral'],['plastiaM','Plastia mitral/anillo'],['rvt','Reemplazo tricuspídeo'],['plastiaT','Plastia tricuspídea/anillo'],['aorta','Aorta'],['tx','Trasplante'],['vad','VAD'],['maze','Maze'],['orejuela','Exclusión orejuela'],['otro','Otro']].map(([k,lbl])=>`<label class="check"><input type="checkbox" data-proc="${k}" ${proc[k]?'checked':''}> ${lbl}</label>`).join('')}</div>`;
let revasc=proc.crm?renderCABG(cab):`<div class="hint">Se habilita cuando se marca CRM.</div>`;
let cec=s.cec||{};let cecBody=`<div class="grid3">${bindSelect('CEC','surgery.cec.used',cec.used,['No','Sí'])}${cec.used==='Sí'?bindField('Tiempo CEC (min)','surgery.cec.minutes',cec.minutes,'number'):''}${cec.used==='Sí'?bindField('Clampeo (min)','surgery.cec.clamp',cec.clamp,'number'):''}${cec.used==='Sí'?bindSelect('Salida exitosa al primer intento','surgery.cec.firstExit',cec.firstExit,['No','Sí','No disponible']):''}${cec.used==='Sí'?bindField('N° reentradas CEC','surgery.cec.reentries',cec.reentries,'number'):''}</div>`;
let transf=s.transfusion||{};let tf=`<div class="grid4">${bindSelect('Transfusión intraoperatoria','surgery.transfusion.yes',transf.yes,['No','Sí'])}${transf.yes==='Sí'?bindField('GR (U)','surgery.transfusion.rbc',transf.rbc,'number'):''}${transf.yes==='Sí'?bindField('Plasma (U)','surgery.transfusion.plasma',transf.plasma,'number'):''}${transf.yes==='Sí'?bindField('Plaquetas','surgery.transfusion.platelets',transf.platelets,'number'):''}</div>`;
return `<div class="card">${section('1. Datos generales y procedimiento',general,'ok','surg_general')}${section('2. Procedimiento realizado',procs,'ok','surg_proc')}${section('3. Revascularización',revasc,proc.crm?'ok':'idle','cabg')}${section('4. Circulación extracorpórea',cecBody,'ok','cec')}${section('5. Transfusión',tf,'ok','transf')}<div class="section open"><div class="section-h"><strong>6. Resumen operatorio</strong><span class="statusdot ok">●</span></div><div class="section-b"><button class="btn primary" id="genSurgSummary">Generar resumen operatorio</button><div id="surgSummaryBox" class="subcard mono">${esc(c.documents?.surgerySummary||'')}</div></div></div></div>`}
function renderCABG(cab){let l=cab.lima||{},r=cab.rima||{},v=cab.venous||{grafts:[]};let venN=parseInt(v.count||0)||0;while(v.grafts.length<venN)v.grafts.push({});if(v.grafts.length>venN)v.grafts=v.grafts.slice(0,venN);let distalCount=(l.yes==='Sí'?1+(l.sequential==='Sí'?(l.seqTargets||[]).length:0):0)+(r.yes==='Sí'?1+(r.sequential==='Sí'?(r.seqTargets||[]).length:0):0)+v.grafts.reduce((a,g)=>a+1+(g.sequential==='Sí'?(g.seqTargets||[]).length:0),0);return `<div class="goodnotice">Derivados: doble mamaria <b>${l.yes==='Sí'&&r.yes==='Sí'?'Sí':'No'}</b> · anastomosis distales estimadas <b>${distalCount}</b></div><div class="subcard"><div class="subhead">LIMA</div><div class="grid3">${bindSelect('LIMA','surgery.cabg.lima.yes',l.yes,['No','Sí'])}${l.yes==='Sí'?bindSelect('Anastomosis distal principal','surgery.cabg.lima.mainTarget',l.mainTarget,['DA proximal','DA media','DA distal']):''}${l.yes==='Sí'?bindSelect('Secuencial','surgery.cabg.lima.sequential',l.sequential,['No','Sí']):''}</div>${l.yes==='Sí'&&l.sequential==='Sí'?`<div class="subtitle">Destinos secuenciales LIMA</div>${multiCheck('surgery.cabg.lima.seqTargets',LIMA_SEQ,l.seqTargets)}`:''}</div><div class="subcard"><div class="subhead">RIMA</div><div class="grid3">${bindSelect('RIMA','surgery.cabg.rima.yes',r.yes,['No','Sí'])}${r.yes==='Sí'?bindSelect('Origen proximal','surgery.cabg.rima.origin',r.origin,['In situ','Libre de aorta','Libre de LIMA']):''}${r.yes==='Sí'?bindSelect('Anastomosis distal principal','surgery.cabg.rima.mainTarget',r.mainTarget,RIMA_DST):''}${r.yes==='Sí'?bindSelect('Secuencial','surgery.cabg.rima.sequential',r.sequential,['No','Sí']):''}</div>${r.yes==='Sí'&&r.sequential==='Sí'?`<div class="subtitle">Destinos secuenciales RIMA</div>${multiCheck('surgery.cabg.rima.seqTargets',RIMA_DST,r.seqTargets)}`:''}</div><div class="subcard"><div class="subhead">Puentes venosos</div><div class="grid3">${bindSelect('Puentes venosos','surgery.cabg.venous.yes',v.yes,['No','Sí'])}${v.yes==='Sí'?bindSelect('Número de puentes','surgery.cabg.venous.count',v.count,['1','2','3','4']):''}</div>${v.yes==='Sí'?v.grafts.map((g,i)=>renderVenousGraft(g,i)).join(''):''}</div>`}
function renderVenousGraft(g,i){return `<div class="subcard"><div class="subhead">Puente venoso ${i+1}</div><div class="grid3">${bindSelect('Anastomosis proximal',`surgery.cabg.venous.grafts.${i}.proximal`,g.proximal,['Aorta','LIMA','RIMA'])}${bindSelect('Anastomosis distal principal',`surgery.cabg.venous.grafts.${i}.mainTarget`,g.mainTarget,VENOUS_DST)}${bindSelect('Secuencial',`surgery.cabg.venous.grafts.${i}.sequential`,g.sequential,['No','Sí'])}</div>${g.sequential==='Sí'?`<div class="subtitle">Destinos secuenciales</div>${multiCheck(`surgery.cabg.venous.grafts.${i}.seqTargets`,VENOUS_DST,g.seqTargets)}`:''}</div>`}

function renderPop(){let c=ccase(),p=c.pop||{},h=p.hemodynamics||{},r=p.resp||{},d=p.drugs||{},pac=p.pacer||{},dr=p.drains||{},lab=p.lab||{};let hemo=`<div class="grid4">${bindField('FC','pop.hemodynamics.hr',h.hr,'number')}${bindField('PAS','pop.hemodynamics.sbp',h.sbp,'number')}${bindField('PAD','pop.hemodynamics.dbp',h.dbp,'number')}${bindField('SatO₂ (%)','pop.hemodynamics.sat',h.sat,'number')}${bindField('Temperatura °C','pop.hemodynamics.temp',h.temp,'number','step="0.1"')}${bindSelect('Swan-Ganz','pop.hemodynamics.swan',h.swan,['No','Sí'])}</div>${h.swan==='Sí'?renderSwan(h):''}`;
let resp=`<div class="grid3">${bindSelect('ARM al ingreso UCO','pop.resp.arm',r.arm,['No','Sí'])}${r.arm==='Sí'?bindSelect('Modo','pop.resp.mode',r.mode,['VCV','PCV','Soporte','Otro']):''}${r.arm==='Sí'?bindField('VT (mL)','pop.resp.vt',r.vt,'number'):''}${r.arm==='Sí'?bindField('FR','pop.resp.rr',r.rr,'number'):''}${r.arm==='Sí'?bindField('PEEP','pop.resp.peep',r.peep,'number'):''}${r.arm==='Sí'?bindField('FiO₂ (%)','pop.resp.fio2',r.fio2,'number'):''}${r.arm==='No'?bindSelect('Oxigenoterapia','pop.resp.o2type',r.o2type,['Aire ambiente','Cánula nasal','Máscara','Alto flujo','VNI','Otro']):''}${r.arm==='No'&&r.o2type&&r.o2type!=='Aire ambiente'?bindField('Flujo O₂ (L/min)','pop.resp.o2flow',r.o2flow,'number','step="0.1"'):''}</div>`;
let drugs=renderDrugSection();let mc=p.mcs||{};let mcs=`<div class="grid3">${bindSelect('Asistencia circulatoria mecánica','pop.mcs.yes',mc.yes,['No','Sí'])}${mc.yes==='Sí'?bindSelect('Tipo','pop.mcs.type',mc.type,['BCIA','Impella','VA-ECMO','LVAD','RVAD','BiVAD','Otro']):''}</div>`;
let pacer=renderPacer(pac);let drains=`<div class="grid4">${bindSelect('Drenajes','pop.drains.yes',dr.yes,['No','Sí'])}${dr.yes==='Sí'?bindField('Mediastinales','pop.drains.mediastinal',dr.mediastinal,'number'):''}${dr.yes==='Sí'?bindField('Pleural derecho','pop.drains.rightPleural',dr.rightPleural,'number'):''}${dr.yes==='Sí'?bindField('Pleural izquierdo','pop.drains.leftPleural',dr.leftPleural,'number'):''}</div>`;
let transf=p.arrivalTransfusion||{};let transfBody=`<div class="grid3">${bindSelect('Transfusión sangre/hemoderivados al ingreso POP','pop.arrivalTransfusion.yes',transf.yes,['No','Sí'])}</div>${transf.yes==='Sí'?`<div class="checkgrid">${['GR','Plasma','Plaquetas','Crioprecipitado','Fibrinógeno','Otro'].map(x=>`<label class="check"><input type="checkbox" data-transf-comp="${x}" ${(transf.components||[]).includes(x)?'checked':''}>${x}</label>`).join('')}</div>`:''}`;
let labBody=`<div class="grid4">${bindSelect('Origen','pop.lab.source',lab.source,['Último laboratorio de quirófano','Primer laboratorio UCO'])}${bindField('Hb','pop.lab.hb',lab.hb,'number','step="0.1"')}${bindField('Hto','pop.lab.hct',lab.hct,'number','step="0.1"')}${bindField('Lactato','pop.lab.lactate',lab.lactate,'number','step="0.1"')}${bindField('pH','pop.lab.ph',lab.ph,'number','step="0.01"')}${bindField('EB','pop.lab.be',lab.be,'number','step="0.1"')}${bindField('K','pop.lab.k',lab.k,'number','step="0.1"')}${bindField('Glucemia','pop.lab.glucose',lab.glucose,'number')}${bindField('Creatinina (opcional)','pop.lab.creatinine',lab.creatinine,'number','step="0.01"')}</div>`;
let evt=`<div class="grid3">${bindSelect('Evento mayor inmediato','pop.majorEvent',p.majorEvent,['No','Sí'])}${p.majorEvent==='Sí'?bindSelect('Tipo','pop.majorEventType',p.majorEventType,['Paro','TV/FV','Shock refractario','Sangrado crítico','Taponamiento','Reintervención','Neurológico','Otro']):''}</div>`;
return `<div class="card">${section('1. Hemodinamia',hemo,'ok','pop_hemo')}${section('2. Respiratorio',resp,'ok','pop_resp')}${section('3. Drogas / infusiones',drugs,'ok','pop_drugs')}${section('4. Asistencia circulatoria',mcs,'ok','pop_mcs')}${section('5. Marcapasos transitorio',pacer,'ok','pop_pacer')}${section('6. Drenajes',drains,'ok','pop_drains')}${section('7. Transfusión en curso al ingreso',transfBody,'ok','pop_transf')}${section('8. Laboratorio de referencia',labBody,'ok','pop_lab')}${section('9. Eventos inmediatos',evt,'ok','pop_events')}<div class="section open"><div class="section-h"><strong>10. Generar ingreso POP</strong><span class="statusdot ok">●</span></div><div class="section-b"><button class="btn primary" id="genPopNote">Generar texto</button><button class="btn" id="copyPopNote">Copiar</button><div class="subcard mono" id="popNoteBox">${esc(c.documents?.popNote||'')}</div></div></div></div>`}
function renderSwan(h){return `<div class="subcard"><div class="subhead">Swan-Ganz / Vigilance</div><div class="grid4">${bindField('AD (mmHg)','pop.hemodynamics.ra',h.ra,'number','step="0.1"')}${bindField('PAP sistólica','pop.hemodynamics.paps',h.paps,'number')}${bindField('PAP diastólica','pop.hemodynamics.papd',h.papd,'number')}${bindField('PAP media','pop.hemodynamics.papm',h.papm,'number')}${bindField('PCP (mmHg)','pop.hemodynamics.pcw',h.pcw,'number','step="0.1"')}${bindField('VM (L/min)','pop.hemodynamics.co',h.co,'number','step="0.1"')}${bindField('IC (L/min/m²)','pop.hemodynamics.ci',h.ci,'number','step="0.1"')}${bindField('RVS','pop.hemodynamics.svr',h.svr,'number')}${bindField('RVP','pop.hemodynamics.pvr',h.pvr,'number')}${bindSelect('Sat venosa disponible','pop.hemodynamics.svo2available',h.svo2available,['No','Sí'])}${h.svo2available==='Sí'?bindField('Sat venosa (%)','pop.hemodynamics.svo2',h.svo2,'number','step="0.1"'):''}</div></div>`}
function renderPacer(p){return `<div class="grid3">${bindSelect('MCP transitorio al ingreso UCO','pop.pacer.yes',p.yes,['No','Sí'])}${p.yes==='Sí'?bindSelect('Cable auricular','pop.pacer.atrial',p.atrial,['No','Sí']):''}${p.yes==='Sí'&&p.atrial==='Sí'?bindSelect('Cantidad cables auriculares','pop.pacer.atrialN',p.atrialN,['1','2']):''}${p.yes==='Sí'?bindSelect('Cable ventricular','pop.pacer.ventricular',p.ventricular,['No','Sí']):''}${p.yes==='Sí'&&p.ventricular==='Sí'?bindSelect('Cantidad cables ventriculares','pop.pacer.ventricularN',p.ventricularN,['1','2']):''}${p.yes==='Sí'?bindField('FC programada','pop.pacer.rate',p.rate,'number'):''}${p.yes==='Sí'?bindSelect('Modo','pop.pacer.mode',p.mode,['VVI','DDD','AAI','Otro']):''}${p.yes==='Sí'?bindField('Voltaje programado (V)','pop.pacer.outputV',p.outputV,'number','step="0.1"'):''}${p.yes==='Sí'?bindField('Umbral de captura (V)','pop.pacer.captureThreshold',p.captureThreshold,'number','step="0.1"'):''}${p.yes==='Sí'?bindSelect('Captura adecuada','pop.pacer.captureOk',p.captureOk,['No','Sí','No evaluado']):''}${p.yes==='Sí'?bindSelect('Falla de captura','pop.pacer.captureFailure',p.captureFailure,['No','Sí','No evaluado']):''}</div>`}
function drugIds(category){return state.drugConfig.filter(x=>x.category===category&&!x.preopOnly).map(x=>[x.id,x.name])}
function renderDrugSection(){let c=ccase(),d=c.pop.drugs||{};return `<div class="notice">Modo estándar: se usan las concentraciones/diluciones configuradas por el hospital y el médico solo selecciona droga + velocidad. “Carga manual de dosis” permite modificar ampollas, cantidad por ampolla y volumen final para esa infusión.</div>${renderDrugGroup('Inotrópicos','inotropes','inotropesYes',drugIds('Inotrópico'))}${renderDrugGroup('Vasopresores','vasopressors','vasopressorsYes',drugIds('Vasopresor'))}${renderDrugGroup('Vasodilatadores','vasodilators','vasodilatorsYes',drugIds('Vasodilatador'))}${renderDrugGroup('Sedación / analgesia','sedation','sedationYes',drugIds('Sedación/analgesia'))}${renderDrugGroup('Antiarrítmicos','antiarrhythmics','antiarrhythmicsYes',drugIds('Antiarrítmico'))}${renderFurosemide()}<div class="subcard"><div class="grid2">${bindSelect('Ácido tranexámico en infusión','pop.drugs.tranexamic',d.tranexamic,['No','Sí'])}</div></div>`}
function renderDrugGroup(title,key,yesKey,choices){let d=ccase().pop.drugs;d[key]??=[];let yes=d[yesKey]||'No';let count=d[key].length||1;if(yes!=='Sí')count=1;while(d[key].length<count)d[key].push({});return `<div class="subcard"><div class="subhead">${title}</div><div class="grid3"><div class="field"><label>${title}</label><select data-drugyes="${yesKey}" data-drugkey="${key}">${opts(['No','Sí'],yes,false)}</select></div>${yes==='Sí'?`<div class="field"><label>Cantidad de drogas</label><select data-drugcount="${key}">${opts(['1','2','3','4'],String(d[key].length||1),false)}</select></div>`:''}</div>${yes==='Sí'?d[key].map((inf,i)=>renderInfusion(inf,key,i,choices)).join(''):''}</div>`}
function renderInfusion(inf,key,i,choices){let cfg=state.drugConfig.find(x=>x.id===inf.drugId);let manual=!!inf.manual||(cfg?.manualOnly);let weight=n(ccase().weight);let calc=calculateDose(inf,cfg,weight);return `<div class="subcard"><div class="subhead">Droga ${i+1}</div><div class="grid3"><div class="field"><label>Droga</label><select data-infusion-drug="${key}|${i}">${opts(choices,inf.drugId)}</select></div><div class="field"><label>Velocidad (mL/h)</label><input type="number" step="0.1" data-infusion-rate="${key}|${i}" value="${esc(inf.rate??'')}"></div><label class="check"><input type="checkbox" data-infusion-manual="${key}|${i}" ${manual?'checked':''}> Carga manual de dosis</label></div>${cfg&&!manual?`<div class="hint">Patrón: ${cfg.units} × ${cfg.amount} ${cfg.amountUnit} en volumen final ${cfg.finalVolume} mL ${cfg.diluent}. Rango de referencia: ${esc(cfg.range||'—')}</div>`:''}${manual?renderManualInfusion(inf,cfg,key,i):''}<div class="dosebox">Dosis calculada: ${calc.text}${calc.warn?` · <span class="dangerText">${esc(calc.warn)}</span>`:''}</div></div>`}
function renderManualInfusion(inf,cfg,key,i){let u=inf.manualUnits??cfg?.units??'',a=inf.manualAmount??cfg?.amount??'',au=inf.manualAmountUnit??cfg?.amountUnit??'mg',vol=inf.manualVolume??cfg?.finalVolume??100,du=inf.manualDoseUnit??cfg?.doseUnit??'mcg/kg/min';return `<div class="grid4" style="margin-top:8px"><div class="field"><label>N° ampollas/unidades</label><input type="number" step="0.1" data-manual="${key}|${i}|manualUnits" value="${esc(u)}"></div><div class="field"><label>Cantidad por ampolla</label><input type="number" step="0.001" data-manual="${key}|${i}|manualAmount" value="${esc(a)}"></div><div class="field"><label>Unidad</label><select data-manual="${key}|${i}|manualAmountUnit">${opts(['mg','mcg','UI'],au,false)}</select></div><div class="field"><label>Volumen final (mL)</label><input type="number" step="0.1" data-manual="${key}|${i}|manualVolume" value="${esc(vol)}"></div><div class="field"><label>Unidad de dosis</label><select data-manual="${key}|${i}|manualDoseUnit">${opts(['mcg/kg/min','mcg/min','mcg/kg/h','mg/kg/h','mg/h','mg/min','UI/min'],du,false)}</select></div></div>`}
function renderFurosemide(){let f=ccase().pop.drugs.furosemide||{};if(f.yes==='Sí'&&!f.volume)f.volume=100;let dose=(n(f.totalMg)&&n(f.volume)&&n(f.rate))?n(f.totalMg)/n(f.volume)*n(f.rate):null;return `<div class="subcard"><div class="subhead">Furosemida</div><div class="grid4">${bindSelect('Infusión de furosemida','pop.drugs.furosemide.yes',f.yes,['No','Sí'])}${f.yes==='Sí'?bindField('Furosemida total (mg)','pop.drugs.furosemide.totalMg',f.totalMg,'number','step="0.1"'):''}${f.yes==='Sí'?bindField('Volumen final (mL)','pop.drugs.furosemide.volume',f.volume||100,'number','step="0.1"'):''}${f.yes==='Sí'?bindField('Velocidad (mL/h)','pop.drugs.furosemide.rate',f.rate,'number','step="0.1"'):''}</div>${f.yes==='Sí'?`<div class="dosebox">Dosis: ${dose!=null?fmt(dose,2)+' mg/h':'—'}</div>`:''}</div>`}
function calculateDose(inf,cfg,weight){if(!cfg&&!inf.manual)return{text:'—'};let manual=!!inf.manual||cfg?.manualOnly;let units=n(manual?inf.manualUnits:cfg?.units), amount=n(manual?inf.manualAmount:cfg?.amount), au=(manual?inf.manualAmountUnit:cfg?.amountUnit)||'mg',vol=n(manual?inf.manualVolume:cfg?.finalVolume),rate=n(inf.rate),du=(manual?inf.manualDoseUnit:cfg?.doseUnit)||'';if(!(units&&amount&&vol&&rate))return{text:'—'};let total=units*amount;let base=total;if(du.startsWith('mcg')){if(au==='mg')base*=1000; else if(au==='UI')return{text:'—',warn:'Unidad incompatible'}}else if(du.startsWith('mg')){if(au==='mcg')base/=1000; else if(au==='UI')return{text:'—',warn:'Unidad incompatible'}}else if(du.startsWith('UI')){if(au!=='UI')return{text:'—',warn:'Unidad incompatible'}}let perHour=base/vol*rate,val=perHour;if(du.endsWith('/min'))val/=60;if(du.includes('/kg/')){if(!weight)return{text:'—',warn:'Falta peso'};val/=weight}return{text:`${fmt(val,du.includes('UI')?3:4)} ${du}`}}

function render72(){let h=ccase().h72||{};return `<div class="card">${section('1. Situación a 72 h',`<div class="grid3">${bindSelect('Ubicación','h72.location',h.location,['UCI','Sala','Otra','Fallecido'])}${bindSelect('ARM actual','h72.arm',h.arm,['No','Sí'])}${bindSelect('Reintubación','h72.reintubation',h.reintubation,['No','Sí','No disponible'])}${bindSelect('Vasoactivos/inotrópicos actuales','h72.vaso',h.vaso,['No','Sí'])}${bindSelect('MCS actual','h72.mcs',h.mcs,['No','Sí'])}</div>`,'ok','h72_state')}${section('2. Outcomes acumulados',`<div class="grid3">${bindSelect('FA/flutter POP','h72.af',h.af,['No','Sí','No disponible'])}${bindSelect('TV/FV','h72.vt',h.vt,['No','Sí','No disponible'])}${bindSelect('AKI máxima','h72.aki',h.aki,['No','KDIGO 1','KDIGO 2','KDIGO 3','No disponible'])}${bindSelect('Nueva TRR','h72.rrt',h.rrt,['No','Sí','No disponible'])}${bindSelect('ACV/AIT','h72.stroke',h.stroke,['No','Sí','No disponible'])}${bindSelect('Reoperación','h72.reop',h.reop,['No','Sí','No disponible'])}</div>`,'ok','h72_events')}</div>`}
function renderDischarge(){let d=ccase().discharge||{};return `<div class="card">${section('1. Estado final',`<div class="grid3">${bindSelect('Estado','discharge.status',d.status,['Alta vivo','Fallecido'])}${bindField('Fecha alta/fallecimiento','discharge.date',d.date,'date')}${d.status==='Alta vivo'?bindSelect('Destino','discharge.destination',d.destination,['Domicilio','Rehabilitación','Otra institución','Otro']):''}</div>`,'ok','discharge_state')}${section('2. Outcomes',`<div class="grid3">${bindSelect('Readmisión UCI','discharge.icuReadmission',d.icuReadmission,['No','Sí','No disponible'])}${bindSelect('MCP definitivo','discharge.permPacer',d.permPacer,['No','Sí','No disponible'])}${bindSelect('Infección documentada','discharge.infection',d.infection,['No','Sí','No disponible'])}${d.infection==='Sí'?bindSelect('Diagnóstico infección','discharge.infectionDx',d.infectionDx,['Neumonía','ITU','Mediastinitis','Infección superficial esternal','Infección profunda esternal','Partes blandas','Bacteriemia','Catéter','Otra']):''}${bindSelect('Sepsis','discharge.sepsis',d.sepsis,['No','Sí','No disponible'])}${bindSelect('Lesión por presión','discharge.pressure',d.pressure,['No','Sí','No disponible'])}${d.pressure==='Sí'?bindSelect('Estadio máximo','discharge.pressureStage',d.pressureStage,['1','2','3','4','No clasificable','Lesión profunda','No documentado']):''}</div>`,'ok','discharge_outcomes')}</div>`}
function renderDocs(){let c=ccase();return `<div class="card pad"><h2 class="title">Documentos</h2><div class="toolbar"><button class="btn" id="genPreopDoc">Generar resumen PREOP</button><button class="btn" id="genSurgSummary2">Generar resumen cirugía</button><button class="btn" id="genPopNote2">Generar ingreso POP</button></div><div class="subtitle">PREOP</div><div class="subcard mono">${esc(c.documents?.preop||'')}</div><div class="subtitle">Cirugía</div><div class="subcard mono">${esc(c.documents?.surgerySummary||'')}</div><div class="subtitle">Ingreso POP</div><div class="subcard mono">${esc(c.documents?.popNote||'')}</div></div>`}
function renderFollowup(){let c=ccase();return `<div class="card pad"><div class="toolbar"><button class="btn primary" id="addFollowup">+ Seguimiento</button></div>${c.followups?.length?c.followups.map((f,i)=>`<div class="subcard"><div class="grid4"><div class="field"><label>Fecha</label><input type="date" data-follow="${i}|date" value="${esc(f.date||'')}"></div><div class="field"><label>Momento</label><select data-follow="${i}|moment">${opts(['30 días','1 año','2 años','3 años','Anual','No programado'],f.moment)}</select></div><div class="field"><label>Estado vital</label><select data-follow="${i}|vital">${opts(['Vivo','Fallecido','Desconocido'],f.vital)}</select></div><div class="field"><label>Internaciones desde último control</label><select data-follow="${i}|admissions">${opts(['No','Sí','Desconocido'],f.admissions)}</select></div></div><div class="field" style="margin-top:8px"><label>Observaciones</label><textarea data-follow="${i}|notes">${esc(f.notes||'')}</textarea></div></div>`).join(''):'<div class="goodnotice">Sin seguimientos cargados.</div>'}</div>`}

function generateSurgerySummary(){let c=ccase(),s=c.surgery,cab=s.cabg||{},parts=[];if(s.procedures?.crm){let l=cab.lima||{},r=cab.rima||{},v=cab.venous||{};let ds=[];if(l.yes==='Sí')ds.push(`LIMA-${l.mainTarget||'DA'}`);if(r.yes==='Sí')ds.push(`RIMA-${r.mainTarget||'destino'}`);(v.grafts||[]).forEach(g=>ds.push(`SV-${g.mainTarget||'destino'}`));parts.push(`CRM${ds.length?' ('+ds.join(', ')+')':''}`)}if(s.procedures?.rva)parts.push('reemplazo valvular aórtico');if(s.procedures?.plastiaM)parts.push('plastia mitral');if(s.procedures?.aorta)parts.push('cirugía de aorta');let text=`Se realizó ${parts.join(' + ')||'procedimiento cardiovascular'}.`;if(s.cec?.used==='Sí')text+=` CEC ${s.cec.minutes||'—'} min, clampeo ${s.cec.clamp||'—'} min.`;if(s.transfusion?.yes==='Sí')text+=` Transfusión intraoperatoria: ${s.transfusion.rbc||0} U GR.`;c.documents??={};c.documents.surgerySummary=text;updateSection('documents');scheduleSave();render()}
function generatePopNote(){let c=ccase(),p=c.pop,h=p.hemodynamics||{},r=p.resp||{},d=p.drugs||{},parts=[];parts.push(`Ingresa a UCO a las ${c.surgery?.ucoTime||'—'} h luego de ${procedureLabel(c)||'cirugía cardiovascular'}.`);if(r.arm==='Sí')parts.push(`En ARM modo ${r.mode||'—'}, VT ${r.vt||'—'} mL, FR ${r.rr||'—'}, PEEP ${r.peep||'—'}, FiO₂ ${r.fio2||'—'}%.`);else if(r.arm==='No')parts.push(`${r.o2type||'Respiración espontánea'}${r.o2flow?` con O₂ ${r.o2flow} L/min`:''}.`);parts.push(`FC ${h.hr||'—'} lpm, TA ${h.sbp||'—'}/${h.dbp||'—'} mmHg, SatO₂ ${h.sat||'—'}%.`);let active=[...(d.inotropes||[]),...(d.vasopressors||[])].filter(x=>x.drugId);if(active.length)parts.push('Soporte: '+active.map(x=>{let cfg=state.drugConfig.find(z=>z.id===x.drugId);return `${cfg?.name||x.drugId} ${calculateDose(x,cfg,n(c.weight)).text}`}).join(', ')+'.');if(p.lab?.lactate)parts.push(`Lactato ${p.lab.lactate} mmol/L.`);let text=parts.join(' ');c.documents??={};c.documents.popNote=text;updateSection('documents');scheduleSave();render()}
function generatePreopDoc(){let c=ccase(),p=c.preop||{},txt=`Paciente ${c.context==='ambulatorio'?'ambulatorio':'internado'} para cirugía cardiovascular. Peso ${c.weight||'—'} kg, talla ${c.height||'—'} cm. FEVI ${p.ef||'—'}%. Creatinina ${p.creatinine||'—'} mg/dL. Hb ${p.hb||'—'} g/dL. Indicación: ${(c.indications||[]).join(', ')||'—'}.`;c.documents??={};c.documents.preop=txt;updateSection('documents');scheduleSave();render()}

function renderDrugConfig(){return `<div class="card pad"><div class="headcase"><div><h2 class="title">Configuración de drogas</h2><div class="smalltxt">Valores iniciales basados en droguitas.xlsx, filas 1–30. Editables para reflejar el estándar real Quirófano/UCO.</div></div><button class="btn" id="resetDrugDefaults">Restaurar valores iniciales</button></div><div class="notice">Se interpreta el volumen configurado como <b>volumen final</b> de la preparación. Esto queda como supuesto de la versión LOCAL-003 y debe confirmarse con el protocolo institucional.</div><div class="tableWrap" style="margin-top:12px"><table class="table"><thead><tr><th>Droga</th><th>Grupo</th><th>Cantidad/ampolla</th><th>Unidad</th><th>N° ampollas</th><th>Vol. final mL</th><th>Diluyente</th><th>Unidad dosis</th><th>Referencia</th></tr></thead><tbody>${state.drugConfig.map((d,i)=>`<tr><td>${esc(d.name)}</td><td>${esc(d.category)}</td><td><input data-drugcfg="${i}|amount" type="number" step="0.001" value="${esc(d.amount??'')}" style="width:90px"></td><td><select data-drugcfg="${i}|amountUnit">${opts(['mg','mcg','UI'],d.amountUnit,false)}</select></td><td><input data-drugcfg="${i}|units" type="number" step="0.1" value="${esc(d.units??'')}" style="width:70px"></td><td><input data-drugcfg="${i}|finalVolume" type="number" step="0.1" value="${esc(d.finalVolume??'')}" style="width:85px"></td><td><input data-drugcfg="${i}|diluent" value="${esc(d.diluent||'')}" style="width:70px"></td><td><select data-drugcfg="${i}|doseUnit">${opts(['mcg/kg/min','mcg/min','mcg/kg/h','mg/kg/h','mg/h','mg/min','UI/min'],d.doseUnit,false)}</select></td><td>${esc(d.range||'')}</td></tr>`).join('')}</tbody></table></div></div>`}
function renderData(){return `<div class="card pad"><h2 class="title">Backup y datos locales</h2><div class="goodnotice">Los datos clínicos de prueba se guardan en <b>data/rcv.db</b> en esta computadora.</div><div class="toolbar" style="margin-top:14px"><a class="btn" href="/api/backup" download>Exportar backup JSON</a><label class="btn">Importar backup <input type="file" id="restoreFile" accept="application/json" hidden></label><button class="btn danger" id="resetAll">Borrar todos los datos de prueba</button></div><div class="smalltxt">La restauración reemplaza el estado actual. La configuración de drogas también forma parte del backup.</div></div>`}

function wire(){
  $$('[data-main]').forEach(b=>b.onclick=()=>{currentMain=b.dataset.main;selectedCaseId=null;render()});
  $('#newCaseBtn')?.addEventListener('click',()=>document.body.insertAdjacentHTML('beforeend',newCaseModal()));
  $('#searchCases')?.addEventListener('input',e=>$$('.caseRow').forEach(r=>r.style.display=r.dataset.search.includes(e.target.value.toLowerCase())?'':'none'));
  $$('[data-tab]').forEach(b=>b.onclick=()=>{currentTab=b.dataset.tab;render()});
  $('#backCases')?.addEventListener('click',()=>{selectedCaseId=null;selectedPatientId=null;render()});
  $$('[data-bind]').forEach(el=>{el.addEventListener('change',bindValue); if(el.tagName==='INPUT')el.addEventListener('blur',bindValue)});
  $$('[data-patient-bind]').forEach(el=>{el.addEventListener('change',bindPatientValue);el.addEventListener('blur',bindPatientValue)});
  $$('[data-indication]').forEach(el=>el.onchange=()=>{let c=ccase();c.indications=$$('[data-indication]:checked').map(x=>x.dataset.indication);updateSection('indication');scheduleSave()});
  $$('[data-planproc]').forEach(el=>el.onchange=()=>{let c=ccase();c.preop.plannedProcedures=$$('[data-planproc]:checked').map(x=>x.dataset.planproc);updateSection('indication');scheduleSave()});
  $$('[data-checklist]').forEach(el=>el.onchange=()=>{let c=ccase();c.preop.checklist??={};c.preop.checklist[el.dataset.checklist]=el.value;updateSection('checklist');scheduleSave()});
  $$('[data-proc]').forEach(el=>el.onchange=()=>{let c=ccase();c.surgery.procedures??={};c.surgery.procedures[el.dataset.proc]=el.checked;updateSection('surg_proc');scheduleSave();render()});
  $$('[data-multi]').forEach(el=>el.onchange=()=>{let c=ccase(),path=el.dataset.multi;let arr=$$(`[data-multi="${CSS.escape(path)}"]:checked`).map(x=>x.value);setByPath(c,path,arr);scheduleSave();render()});
  $$('[data-drugyes]').forEach(el=>el.onchange=()=>{let d=ccase().pop.drugs,key=el.dataset.drugkey;d[el.dataset.drugyes]=el.value;if(el.value==='Sí'&&!d[key].length)d[key]=[{}];scheduleSave();render()});
  $$('[data-drugcount]').forEach(el=>el.onchange=()=>{let arr=ccase().pop.drugs[el.dataset.drugcount],cnt=parseInt(el.value);while(arr.length<cnt)arr.push({});arr.length=cnt;scheduleSave();render()});
  $$('[data-infusion-drug]').forEach(el=>el.onchange=()=>{let [key,i]=el.dataset.infusionDrug.split('|'),inf=ccase().pop.drugs[key][+i];inf.drugId=el.value;let cfg=state.drugConfig.find(x=>x.id===el.value);inf.manual=!!cfg?.manualOnly;scheduleSave();render()});
  $$('[data-infusion-rate]').forEach(el=>{el.oninput=()=>{let [key,i]=el.dataset.infusionRate.split('|');ccase().pop.drugs[key][+i].rate=el.value;scheduleSave()};el.onchange=()=>render()});
  $$('[data-infusion-manual]').forEach(el=>el.onchange=()=>{let [key,i]=el.dataset.infusionManual.split('|');ccase().pop.drugs[key][+i].manual=el.checked;scheduleSave();render()});
  $$('[data-manual]').forEach(el=>el.onchange=()=>{let [key,i,field]=el.dataset.manual.split('|');ccase().pop.drugs[key][+i][field]=el.value;scheduleSave();render()});
  $$('[data-transf-comp]').forEach(el=>el.onchange=()=>{let a=$$('[data-transf-comp]:checked').map(x=>x.dataset.transfComp);ccase().pop.arrivalTransfusion??={};ccase().pop.arrivalTransfusion.components=a;scheduleSave()});
  $$('[data-follow]').forEach(el=>el.onchange=()=>{let [i,k]=el.dataset.follow.split('|');ccase().followups[+i][k]=el.value;scheduleSave()});
  $$('[data-drugcfg]').forEach(el=>el.onchange=()=>{let [i,k]=el.dataset.drugcfg.split('|');state.drugConfig[+i][k]=el.value;scheduleSave()});
  $('.section-h')&&$$('.section-h').forEach(h=>h.onclick=()=>h.parentElement.classList.toggle('open'));
  $('#genSurgSummary')?.addEventListener('click',generateSurgerySummary);$('#genSurgSummary2')?.addEventListener('click',generateSurgerySummary);
  $('#genPopNote')?.addEventListener('click',generatePopNote);$('#genPopNote2')?.addEventListener('click',generatePopNote);
  $('#genPreopDoc')?.addEventListener('click',generatePreopDoc);
  $('#copyPopNote')?.addEventListener('click',()=>navigator.clipboard?.writeText(ccase().documents?.popNote||''));
  $('#addFollowup')?.addEventListener('click',()=>{ccase().followups.push({date:'',moment:'',vital:'',admissions:'',notes:''});scheduleSave();render()});
  $('#resetDrugDefaults')?.addEventListener('click',()=>{if(confirm('¿Restaurar la configuración inicial de drogas?')){state.drugConfig=structuredClone(DEFAULT_DRUGS);scheduleSave();render()}});
  $('#restoreFile')?.addEventListener('change',async e=>{let f=e.target.files[0];if(!f)return;try{let obj=JSON.parse(await f.text());await api('/api/restore',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(obj)});location.reload()}catch(err){alert('Backup inválido')}});
  $('#resetAll')?.addEventListener('click',async()=>{if(confirm('Esto borrará TODOS los datos locales de prueba. ¿Continuar?')){await api('/api/reset',{method:'POST'});location.reload()}});
}
function globalClick(e){let t=e.target.closest('[data-open-case]');if(t){let [p,c]=t.dataset.openCase.split('|');selectedPatientId=p;selectedCaseId=c;currentTab='preop';render();return}if(e.target.id==='closeModalBtn'){$('#modal')?.remove();return}if(e.target.id==='createCaseBtn'){createCase();return}}
document.addEventListener('click',globalClick);
document.addEventListener('change',e=>{if(e.target.id==='npContext'){let amb=e.target.value==='ambulatorio';$('#npCharacter').innerHTML=amb?'<option>Programada</option>':'<option>Programada</option><option>Urgente</option><option>Emergencia</option>';$('#npCharacter').disabled=amb;$('#npAdmissionWrap').style.display=amb?'none':'block'}});

load().catch(e=>{$('#app').innerHTML=`<div class="shell"><div class="notice">Error al iniciar: ${esc(e.message)}</div></div>`});
